sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var messageId = buildMessageId();
    if (current.message_id == '') {
        current.message_id = messageId;
        current.update();
    }

    try {
        var retryCount = 1;
        while (retryCount <= 3) {
            var r = new sn_ws.RESTMessageV2('HSBC Symphony API', current.type);
            r.setStringParameterNoEscape('symphony_base_uri', gs.getProperty('x_hsb11_mss_sw.symphony_uri'));
            r.setStringParameterNoEscape('symphony_token', gs.getProperty('x_hsb11_mss_sw.hsbcmss_symphony_api_token'));
            r.setStringParameterNoEscape('message_id', messageId);
            if (current.type == 'Update Message') {
                r.setStringParameterNoEscape('encrypted_message_id', current.encrypted_message_id);
            }
            r.setStringParameterNoEscape('sendto', buildSendTo(current.sendto));
            r.setStringParameterNoEscape('message_body', current.message_body);
            r.setStringParameterNoEscape('servicenow_template_name', current.servicenow_template_name);
            current.state = 'Processing';
            var response = r.executeAsync();
            var responseBody = response.getBody();
            var httpStatus = response.getStatusCode();
            var responseBodyObj = JSON.parse(responseBody);
            if (httpStatus == '202' || httpStatus == '200') {
                current.encrypted_message_id = responseBodyObj.metadata[0].encryptedMessageId;
                current.response_body = responseBody;
                current.response_code = httpStatus;
                current.response_date = new GlideDateTime();
                current.state = "Processed";
				break;
            } else {
                current.response_code = httpStatus;
                current.error_body = responseBody;
                current.response_message = response.getErrorMessage();
                current.state = 'Error';
				//gs.info("Retry Count: "+retryCount);
				retryCount += 1;
            }
        }
		current.update();
    } catch (ex) {
        current.state = 'Error';
        current.response_message = ex.message;
        current.update();
    }


    function buildSendTo(text) {
        var outputStr = text.split(',');
        var strArr = [];
        for (var i = 0; i < outputStr.length; i++) {
            strArr.push('"' + outputStr[i] + '"');
        }
        return strArr.join();
    }

    function buildMessageId() {
        var uuid = gs.generateGUID();
        var formattedUuid = uuid.substring(0, 8) + '-' + uuid.substring(8, 12) + '-' + uuid.substring(12, 16) + '-' + uuid.substring(16, 20) + '-' + uuid.substring(20);
        return formattedUuid;
    }
})(current, previous);
